window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"EzTk2yrlxMg","speaker":"Nikos Christodoulides","role":"President","country":"Cyprus","region":"Europe","url":"https://www.youtube.com/watch?v=EzTk2yrlxMg","date":"20260923","title":"🇨🇾 Cyprus - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1150,"words":2069,"counts":{"claims":33,"promises":2,"attacks":4},"topics":[{"topic":"Cyprus reunification","share":0.1659,"seconds":191},{"topic":"UN reform","share":0.1286,"seconds":148},{"topic":"UN principles","share":0.1224,"seconds":141},{"topic":"Cyprus sovereignty","share":0.1116,"seconds":128},{"topic":"Cyprus UN relations","share":0.0705,"seconds":81},{"topic":"Cyprus diplomacy","share":0.064,"seconds":74},{"topic":"Cyprus environment","share":0.0608,"seconds":70},{"topic":"Cyprus EU relations","share":0.0587,"seconds":68},{"topic":"Cyprus human rights","share":0.0554,"seconds":64},{"topic":"Cyprus economy","share":0.0549,"seconds":63},{"topic":"Israel Palestine conflict","share":0.0538,"seconds":62},{"topic":"Cyprus Turkey relations","share":0.0535,"seconds":62}],"timeline":[[10,82,null],[84,153,"UN principles"],[155,227,"UN principles"],[228,313,"UN reform"],[315,378,"UN reform"],[379,441,"Israel Palestine conflict"],[443,506,"Cyprus economy"],[508,578,"Cyprus environment"],[579,647,"Cyprus EU relations"],[648,729,"Cyprus UN relations"],[731,806,"Cyprus sovereignty"],[807,871,"Cyprus human rights"],[872,934,"Cyprus Turkey relations"],[935,997,"Cyprus reunification"],[998,1062,"Cyprus reunification"],[1063,1129,"Cyprus reunification"],[1130,1203,"Cyprus diplomacy"],[1205,1258,"Cyprus sovereignty"]],"stances":{"UN principles":"Nikos Christodoulides argues that foundational values like the UN Charter and international law must be protected during times of uncertainty to address new realities.","UN reform":"Nikos Christodoulides states that the United Nations must evolve to respond to current global needs and acknowledges the Secretary General's leadership in this effort.","Israel Palestine conflict":"Nikos Christodoulides states that Cyprus proposed and is currently operating a maritime humanitarian corridor to address the situation in Gaza.","Cyprus economy":"Nikos Christodoulides states that Cyprus has served as a safe harbor for evacuations and provided humanitarian assistance to countries facing natural disasters.","Cyprus environment":"Nikos Christodoulides states that cooperation is the only answer to the climate crisis and describes Cyprus's regional initiatives on climate change and aerial firefighting as concrete steps to strengthen collective capacity.","Cyprus EU relations":"Nikos Christodoulides highlights Cyprus's successful leadership of the EU Council and its role in fostering regional cooperation through specific security initiatives.","Cyprus UN relations":"Nikos Christodoulides asserts that Cyprus has actively fulfilled its responsibilities as a small nation by leading, negotiating, and contributing to international efforts while emphasizing the necessity of avoiding isolation.","Cyprus sovereignty":"Nikos Christodoulides asserts that Turkey's 52-year occupation of Cyprus constitutes a flagrant violation of international law and the UN Charter, resulting in displacement and human rights abuses.","Cyprus human rights":"Nikos Christodoulides asserts that the principles of sovereign and territorial integrity must be applied consistently and without exception, regardless of time or power dynamics.","Cyprus Turkey relations":"Nikos Christodoulides states that Turkey is acting contrary to the principles of international law and sovereignty it claims to support, specifically regarding Cyprus.","Cyprus reunification":"Nikos Christodoulides asserts that the UN Security Council framework for a bizonal, bicommunal federation is the only basis for a solution and expresses readiness to resume negotiations.","Cyprus diplomacy":"Nikos Christodoulides asserts that Cyprus believes in a united nation and a multilateral system where small states are active participants rather than being marginalized."},"claims":[{"t":100,"quote":"international law, the UN charter, respect for sovereign and territorial integrity, the peaceful settlement of disputes, respect for human rights, the equality of states. All these are not principles of the past.","topic":"UN principles","kind":"fact"},{"t":161,"quote":"Restoring trust, managing transformation, a united nation that delivers for all.","topic":"UN principles","kind":"fact"},{"t":189,"quote":"For small-sized countries, the principle of equality of states is fundamental and it has formed the biding trust between us.","topic":"UN principles","kind":"fact"},{"t":268,"quote":"The UN80 initiative is an important part of this effort.","topic":"UN reform","kind":"fact"},{"t":289,"quote":"This moment of reform also comes as the UN Secretary General approaches the completion of a decade leading this Cyrus wishes to acknowledge his leadership during a period of extraordinary global developments, his steadfast commitment to multilateralism and his effort to strengthen and reform the UN.","topic":"UN reform","kind":"self_credit"},{"t":342,"quote":"Great powers have scale. Smaller states must have persuasion.","topic":"UN reform","kind":"fact"},{"t":369,"quote":"And the Republic of Cyprus has consistently sought to do exactly that.","topic":"UN reform","kind":"self_credit"},{"t":397,"quote":"Following the Hamas 2023 terrorist attack and the devastating humanitarian situation in Gaza, Cyprus has put forward the Amalia maritime humanitarian corridor.","topic":"Israel Palestine conflict","kind":"fact"},{"t":430,"quote":"That idea became a proposal and evolve into a functioning humanitarian route, one that keeps delivering as we speak.","topic":"Israel Palestine conflict","kind":"self_credit"},{"t":467,"quote":"In the last three years alone, we help evacuate thousands of citizens from 70 different countries.","topic":"Cyprus economy","kind":"number"},{"t":485,"quote":"Cypus was among the first responders following the catastrophic earthquake in Venezuela and the flash floods in Nepal.","topic":"Cyprus economy","kind":"fact"},{"t":523,"quote":"The interweave and political realities that we are facing are further amplified by the climate crisis.","topic":"Cyprus environment","kind":"fact"},{"t":536,"quote":"This is the purpose of Cyprus's regional initiative on climate change to bring together countries of the region thus strengthening our collective capacity for adaptation, mitigation and resilience.","topic":"Cyprus environment","kind":"self_credit"},{"t":553,"quote":"Another manifestation of this is the Cyprus regional aerial firefighting station hosted at PAOS air base and supported by the European Union.","topic":"Cyprus environment","kind":"fact"},{"t":605,"quote":"In this four year of operation, it has provided specialized training to thousand of government officials from more than 50 countries from the Middle East, Africa, and Europe.","topic":"Cyprus EU relations","kind":"fact"},{"t":635,"quote":"For six months, a country of fewer than 1 million people assumed the responsibility of steering the work of a union of 450 million citizens.","topic":"Cyprus EU relations","kind":"fact"},{"t":648,"quote":"For Cyprus, this was both a responsibility and an opportunity to listen, to negotiate, to build consensus, and to help the European Union and its member states move forward on common priorities.","topic":"Cyprus UN relations","kind":"fact"},{"t":677,"quote":"Our position is clear. In an era of poly crisis, isolation is the antithesis of and a luxury we cannot afford.","topic":"Cyprus UN relations","kind":"fact"},{"t":691,"quote":"Cyprus proved to be an active and responsible party of the international community, a contributor in crisis management, an actor in humanitarian assistance, a proponent of regional synergies, and a defender of the protection of human rights","topic":"Cyprus UN relations","kind":"self_credit"},{"t":741,"quote":"52 years have passed since the illegal Turkish invasion of Cyprus.","topic":"Cyprus sovereignty","kind":"fact"},{"t":754,"quote":"An ongoing flagrant violation of international law with more than a third of the territory of Cyprus remaining under Turkish occupation.","topic":"Cyprus sovereignty","kind":"fact"},{"t":765,"quote":"For 52 years, the tens of thousands of displaces and their descendants are prevented from returning to their homes.","topic":"Cyprus sovereignty","kind":"fact"},{"t":821,"quote":"And for 52 years, the principles at stake have remained the same.","topic":"Cyprus human rights","kind":"fact"},{"t":853,"quote":"UN resolutions cannot be upheld in one case and disregarded fully disregarded in another.","topic":"Cyprus human rights","kind":"fact"},{"t":906,"quote":"I listened very carefully to the speech of President Eertoan yesterday. references to international law, to the respect for the sovereignty and territorial integrity of all states, to illegal occupation, to the drama of refugees.","topic":"Cyprus Turkey relations","kind":"fact"},{"t":926,"quote":"Yet, in relation to my country, in relation to Cyprus, Turkey is doing exactly the opposite.","topic":"Cyprus Turkey relations","kind":"fact"},{"t":960,"quote":"The UN Security Council has established the framework for the solution of the Cypus problem.","topic":"Cyprus reunification","kind":"fact"},{"t":967,"quote":"That framework of a bzonal by communal federation with political equality remains the only basis on which a comprehensive settlement must be reached","topic":"Cyprus reunification","kind":"fact"},{"t":998,"quote":"The relevant UN Security Council resolutions, international law and the law, values and principles of the European Union.","topic":"Cyprus reunification","kind":"fact"},{"t":1063,"quote":"Our determination to reunify our island is firm.","topic":"Cyprus reunification","kind":"fact"},{"t":1146,"quote":"We believe in a united nation that protects the principle of its charter and has the capacity to act upon them.","topic":"Cyprus diplomacy","kind":"fact"},{"t":1156,"quote":"We believe in a multilateral system in which every state has both rights and And we believe that small-sized states have a particular role to play not on the margins of international affairs but as active participants in shaping our common future.","topic":"Cyprus diplomacy","kind":"fact"},{"t":1207,"quote":"despite the challenges because of the Turkish occupation, we remain resilient as stefast in our faith in the multilateral system.","topic":"Cyprus sovereignty","kind":"fact"}],"promises":[{"t":979,"quote":"I remain fully committed to achieving a factional and viable solution.","topic":"Cyprus reunification","kind":"promise"},{"t":985,"quote":"I'm ready I'm ready to resume negotiations from where they left off building on the substantial work already achieved.","topic":"Cyprus reunification","kind":"promise"}],"attacks":[{"t":744,"quote":"illegal Turkish invasion of Cyprus. An act of aggression violating the core principles of the UN charter.","topic":"Cyprus sovereignty","target":"Turkey"},{"t":780,"quote":"Turkey, still in defiance of its clear and very specific obligations set out in the relevant UN resolutions.","topic":"Cyprus sovereignty","target":"Turkey"},{"t":926,"quote":"Yet, in relation to my country, in relation to Cyprus, Turkey is doing exactly the opposite.","topic":"Cyprus Turkey relations","target":"Turkey"},{"t":946,"quote":"But politicians are judged not by the words but by their deeds. And if Mr. Etoan wants to quote from the charter, he must first apply the charter.","topic":"Cyprus reunification","target":"Unnamed opponents"}],"greece":[{"t":648,"quote":"For Cyprus, this was both a responsibility and an opportunity to listen, to negotiate, to build consensus, and to help the European Union and its member states move forward on common priorities.","refers":["Cyprus"],"tone":"conciliatory","el":"Ο Πρόεδρος τόνισε ότι για την Κύπρο η κατάσταση ήταν ευκαιρία και ευθύνη να ακούσει, να διαπραγματευτεί και να χτίσει συναίνεση με την ΕΕ.","en":"The President stated that for Cyprus, the situation presented both a responsibility and an opportunity to listen, negotiate, and build consensus with the EU."},{"t":731,"quote":"For my country, for Cyprus, this is not an abstract principle. It is a painful existential","refers":["Cyprus"],"tone":"supportive","el":"Ο Πρόεδρος αναφέρει ότι η αρχή της συνέπειας στην εφαρμογή του διεθνούς δικαίου δεν είναι αφηρημένη για την Κύπρο, αλλά αποτελεί ουσιαστικό και επώδυνο ζήτημα για το κράτος.","en":"The President states that the principle of consistency in applying international law is not abstract for Cyprus but constitutes a substantive and painful issue for the state."},{"t":741,"quote":"52 years have passed since the illegal Turkish invasion of Cyprus. An act of aggression violating the core principles of the UN charter. An ongoing flagrant violation of international law with more than a third of the territory of Cyprus remaining under Turkish occupation.","refers":["Cyprus"],"tone":"supportive","el":"Ο ομιλητής καταγγέλλει την παράνομη τουρκική εισβολή στην Κύπρο ως πράξη επιθετικής παραβίασης του Χάρτη του ΟΗΕ και τονίζει ότι ένα τρίτο του εδάφους της Κύπρου παραμένει υπό τουρκική κατοχή.","en":"The speaker condemns the illegal Turkish invasion of Cyprus as an act of aggression violating the UN Charter and emphasizes that one-third of the island's territory remains under Turkish occupation."},{"t":926,"quote":"Yet, in relation to my country, in relation to Cyprus, Turkey is doing exactly the opposite. Hipposity of the highest form.","refers":["Cyprus"],"tone":"critical","el":"Ο ομιλητής δηλώνει ότι η Τουρκία ενεργεί με τον αντίθετο τρόπο σε σχέση με την Κύπρο και χαρακτηρίζει αυτή τη συμπεριφορά ως κορυφαίας μορφής υποκρισία.","en":"The speaker states that Turkey is acting in the exact opposite manner regarding Cyprus and characterizes this behavior as hypocrisy of the highest form."},{"t":1031,"quote":"A settlement that allows Greek and Turkish criates, Maronites, Armenians, and Latins to live together in peace, security, and prosperity.","refers":["Cyprus"],"tone":"conciliatory","el":"Ο ομιλητής εκφράζει την επιθυμία για μια συμφωνία που θα επιτρέπει στους Έλληνες και Τούρκους Κύπριους, καθώς και σε άλλες κοινότητες, να ζουν μαζί με ειρήνη και ασφάλεια.","en":"The speaker expresses a desire for a settlement allowing Greeks and Turks, along with other communities, to live together in peace and security."},{"t":1142,"quote":"For Cyprus, there is no such dilemma. We believe in a united nation","refers":["Cyprus"],"tone":"conciliatory","el":"Ο ομιλητής δηλώνει ότι για την Κύπρο δεν υπάρχει δίλημμα και υποστηρίζει την ενότητα του έθνους.","en":"The speaker states that for Cyprus there is no dilemma and expresses support for a united nation."}],"said":[{"topic":"Cyprus reunification","said":0.1659,"reported":0.2778,"articles":5},{"topic":"UN reform","said":0.1286,"reported":0.0,"articles":0},{"topic":"UN principles","said":0.1224,"reported":0.2222,"articles":4},{"topic":"Cyprus sovereignty","said":0.1116,"reported":0.2222,"articles":4},{"topic":"Cyprus UN relations","said":0.0705,"reported":0.0556,"articles":1},{"topic":"Cyprus diplomacy","said":0.064,"reported":0.0,"articles":0},{"topic":"Cyprus environment","said":0.0608,"reported":0.0,"articles":0},{"topic":"Cyprus EU relations","said":0.0587,"reported":0.0,"articles":0},{"topic":"Cyprus human rights","said":0.0554,"reported":0.0,"articles":0},{"topic":"Cyprus economy","said":0.0549,"reported":0.0,"articles":0},{"topic":"Israel Palestine conflict","said":0.0538,"reported":0.0,"articles":0},{"topic":"Cyprus Turkey relations","said":0.0535,"reported":0.2222,"articles":4}],"pickup":[{"outlet":"Proto Thema","date":"2026-09-23","title":"Χριστοδουλίδης σε Ερντογάν στον ΟΗΕ: Αν επικαλείστε τον Χάρτη, πρέπει πρώτα να τον εφαρμόζετε, μέγιστη υποκρισία η στάση της Τουρκίας","url":"https://www.protothema.gr/world/article/1883551/hristodoulidis-erdogan-oie-an-epikaleiste-ton-harti-prepei-prota-na-efarmozete-megisti-upokrisia-i-stasi-tis-tourkias","tone":"favourable"},{"outlet":"Iefimerida","date":"2026-09-23","title":"Επίθεση Χριστοδουλίδη στον Ερντογάν από το βήμα του ΟΗΕ: Η διχοτόμηση δεν θα γίνει αποδεκτή","url":"https://www.iefimerida.gr/kosmos/hristodoylidis-i-dihotomisi-den-tha-ginei-apodekti","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-23","title":"Χριστοδουλίδης: Η διχοτόμηση της Κύπρου δεν είναι αποδεκτή – Η Τουρκία να επιτρέψει ουσιαστικές συνομιλίες","url":"https://www.in.gr/2026/09/23/world/xristodoulidis-i-dixotomisi-tis-kyprou-den-einai-apodekti-i-tourkia-na-epitrepsei-ousiastikes-synomilies","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-23","title":"ΟΗΕ: Ο Χριστοδουλίδης κάλεσε τον Ερντογάν να επιτρέψει ουσιαστικές διαπραγματεύσεις για το Κυπριακό","url":"https://www.flash.gr/oie-o-christodoylidis-kalese-ton-erntogan-na-epitrepsei-oysiastikes-diapragmateyseis-gia-to-kypriako-1082706","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-24","title":"Στο τραπέζι τριμερής Γκουτέρες με Χριστοδουλίδη και Ερχιουρμάν","url":"https://www.protothema.gr/politics/article/1884203/sto-trapezi-trimeris-gouteres-me-hristodoulidi-kai-erhiourman","tone":"neutral"}],"transcript":[{"t":10,"topic":null,"text":"The assembly will hear an address by His Excellency Nikos Christa Douides, President of the Republic of Cyprus. I request protocol to please escort his excellency and invite him to address the assembly. Mr. President, excellencies, as the UN Secretary General reminded us a few years ago, the United Nations is a product of hope. 81 years after its birth, that hope is being tested. including artificial intelligence, is advancing at rapid speed. Climate change is reshaping our The international landscape is becoming more complex, more contested, and more The international order is not simply changing."},{"t":84,"topic":"UN principles","text":"It is being tested in But it is in such times of uncertainty that the foundational values of must be protected. international law, the UN charter, respect for sovereign and territorial integrity, the peaceful settlement of disputes, respect for human rights, the equality of states. All these are not principles of the past. There are principles that transcend time, the essential ingredient for the present and for the future. The challenge before us is therefore clear. As the world changes, our institutions must be able to respond to new realities and threats while guided by the painful lessons of history and the vision of the founding fathers of this organization."},{"t":155,"topic":"UN principles","text":"And this is the essence of the theme of the 81st general assembly. Restoring trust, managing transformation, a united nation that delivers for all. Ladies and gentlemen, transformation is What must remain constant is the UN chapter as our compass. It directs all of us irrespective of power, size and leverage. For small-sized countries, the principle of equality of states is fundamental and it has formed the biding trust between us. We rely on an international system in which sovereignty and territorial integrity are respected. We expect international law including the UN convention on the law of the sea to be applied consistently. We believe in the peaceful resolution of disputes and we demand that the rights of every state be protected."},{"t":228,"topic":"UN reform","text":"These are the integral elements of our collective trust and this is the code of conduct of Cyprus's diplomatic And in a rapidly changing world, smallsiz states must seek synergies while continuing to pursue strategic Preserving trust also requires institutions capable of responding to the world as it is today. The United Nations must therefore continue to evolve. The UN80 initiative is an important part of this effort. The pact for the future and the 2030 agenda and its sustainable development goals are also part of the effort to ensure that multilateral cooperation can respond to the needs of our time. This moment of reform also comes as the UN Secretary General approaches the completion of a decade leading this Cyrus wishes to acknowledge his leadership during a period of extraordinary global developments, his steadfast commitment to multilateralism and his effort to strengthen and reform the UN."},{"t":315,"topic":"UN reform","text":"But reforming our structural setup is only part of the answer. What is also needed is a genuine willingness of member states to contribute to to contribute and protect the multilateral system. After all, states bring different capabilities, experiences and perspectives. Great powers have scale. Smaller states must have persuasion. We cannot compel but we can coalesce. We cannot dictate outcomes, but together we can help shape them. There is no doubt that the challenges of today require cooperation and partnerships based on the knowledge of regions and of the realities. And the Republic of Cyprus has consistently sought to do exactly that. And of course, it has built the capabilities for it."},{"t":379,"topic":"Israel Palestine conflict","text":"Our geographical position at the crossroads of Europe, Asia and Africa place us close to some of the most complex dynamics of our world. At the same time, it give us the opportunity to actively contribute to address them. Following the Hamas 2023 terrorist attack and the devastating humanitarian situation in Gaza, Cyprus has put forward the Amalia maritime humanitarian corridor. Cypus could offer something specific. it geographical position, its infrastructure, its excellent relationship with all countries in the region and the will to engage with international partners through cooperation including with the UN 2720 mechanism. That idea became a proposal and evolve into a functioning humanitarian route, one that keeps delivering as we speak."},{"t":443,"topic":"Cyprus economy","text":"Cypus has also played a constructive role in times of emergency. When third country nationals needed to be evacuated from our neighborhood, my country has served time and time again as a safe harbor. Our infrastructure and our resources have been made available in order to facilitate safe passage for people in danger. In the last three years alone, we help evacuate thousands of citizens from 70 different countries. And through Cyprus Aid, we have provided humanitarian assistance to countries facing natural disasters. Cypus was among the first responders following the catastrophic earthquake in Venezuela and the flash floods in Nepal. The devastating humanitarian situation in Sudan and the wider Sahel region have also been a priority for my country with a large percentage of our resources directed to the region."},{"t":508,"topic":"Cyprus environment","text":"Ladies and gentlemen, rising temperatures, water scarcity, and extreme weather affect us all, transcending borders and politics in the Eastern Mediterranean and the Middle East. The interweave and political realities that we are facing are further amplified by the climate crisis. Cooperation is therefore the only answer. This is the purpose of Cyprus's regional initiative on climate change to bring together countries of the region thus strengthening our collective capacity for adaptation, mitigation and resilience. Another manifestation of this is the Cyprus regional aerial firefighting station hosted at PAOS air base and supported by the European Union. It offers an an operational hub for aerial firefighting and rapid response and a center of excellence for training, and capacity building."},{"t":579,"topic":"Cyprus EU relations","text":"Reflecting its emphasis on regional ownership, it brings together partners from the Middle East, North Africa, and the Gulf. This commitment to regional cooperation, regional engagement is also demonstrated through the cyber [snorts] center for land, open seas and port security jointly created with the United States. In this four year of operation, it has provided specialized training to thousand of government officials from more than 50 countries from the Middle East, Africa, and Europe. Excellencies, the ability to bring different interests together was also at the heart of the Cyus Presidency of the Council of the European Union during the first half of this year. For six months, a country of fewer than 1 million people assumed the responsibility of steering the work of a union of 450 million citizens."},{"t":648,"topic":"Cyprus UN relations","text":"For Cyprus, this was both a responsibility and an opportunity to listen, to negotiate, to build consensus, and to help the European Union and its member states move forward on common priorities. Our size did not diminish the responsibility to lead, nor did it diminish our ability to fulfill it. Our position is clear. In an era of poly crisis, isolation is the antithesis of and a luxury we cannot afford. Cyprus proved to be an active and responsible party of the international community, a contributor in crisis management, an actor in humanitarian assistance, a proponent of regional synergies, and a defender of the protection of human rights and Esteemed delegates, in this time of transformation, the credibility of the UN must be safeguarded and credibility requires consistency in the application of international law."},{"t":731,"topic":"Cyprus sovereignty","text":"For my country, for Cyprus, this is not an abstract principle. It is a painful existential 52 years have passed since the illegal Turkish invasion of Cyprus. An act of aggression violating the core principles of the UN charter. An ongoing flagrant violation of international law with more than a third of the territory of Cyprus remaining under Turkish occupation. For 52 years, the tens of thousands of displaces and their descendants are prevented from returning to their homes. For 52 years, Varosa remains sealed off with Turkey, still in defiance of its clear and very specific obligations set out in the relevant UN resolutions. For 52 years, we are experiencing violations of fundamental human rights, the destruction of religious and cultural heritage, and the organized transfer of settlers amounting to de demographic change."},{"t":807,"topic":"Cyprus human rights","text":"Pain and immense suffering are the daily reality of the relatives of the missing persons that to this day are demanding answers as to the fate of their loved ones. And for 52 years, the principles at stake have remained the same. Respect for sovereign and territorial integrity are not rhetorical vehicles, nor are they to be applied selectively depending on who the perpetrator is. These principles do not become less important with the passage of time nor do the resolutions of this organization. UN resolutions cannot be upheld in one case and disregarded fully disregarded in another. And the sovereign and territorial integrity of a state cannot depend on its size, its power or the passage of the time."},{"t":872,"topic":"Cyprus Turkey relations","text":"And this is not only a question for Cyprus. It goes to the cred credibility of the international system itself. If we ask states to believe in multilateralism, if we expect them to be active contributors, then they must be able to trust that the principles and decisions of our institutions will be upheld without exception. Ladies and gentlemen, I listened very carefully to the speech of President Eertoan yesterday. references to international law, to the respect for the sovereignty and territorial integrity of all states, to illegal occupation, to the drama of refugees. Yet, in relation to my country, in relation to Cyprus, Turkey is doing exactly the opposite."},{"t":935,"topic":"Cyprus reunification","text":"Hipposity of the highest form. President Eran yesterday also quoted extensively from the UN charter. But politicians are judged not by the words but by their deeds. And if Mr. Etoan wants to quote from the charter, he must first apply the charter. The UN Security Council has established the framework for the solution of the Cypus problem. That framework of a bzonal by communal federation with political equality remains the only basis on which a comprehensive settlement must be reached and I remain fully committed to achieving a factional and viable solution. I'm ready I'm ready to resume negotiations from where they left off building on the substantial work already achieved. The common ground is there."},{"t":998,"topic":"Cyprus reunification","text":"The relevant UN Security Council resolutions, international law and the law, values and principles of the European Union. What is now required is political will by all parties and genuine willingness to return to meaningful negotiations to engage seriously to build on the body of work already achieved and to reach a settlement that reunifies our country and our people. A settlement that allows Greek and Turkish criates, Maronites, Armenians, and Latins to live together in peace, security, and prosperity. On my side, let me repeat it and fully because, ladies and gentlemen, division will not be accepted. This cannot and will not be the future for my country and my people ever."},{"t":1063,"topic":"Cyprus reunification","text":"Our determination to reunify our island is firm. I therefore call on my Turkish criate compatriots to perceive our future together as the opportunity for prosperity. And of course, I call on President Eran to give the green light for substantive negotiations within the UN agreed framework. Excellencies, I mentioned several times how change is inevitable, but the choices choices we make in response to change are ours. For countries like Cyprus, the answer must be cooperation with purpose. Partnerships that deliver when they are needed, formed by the belief that in times of need, we must act together. This is the choice to make. We can allow divisions to weaken the institutions we build together, or we can choose to strengthen them."},{"t":1130,"topic":"Cyprus diplomacy","text":"We can allow differences in power to determine whose voice matters or we can reaffirm the principles on which this organization was founded. For Cyprus, there is no such dilemma. We believe in a united nation that protects the principle of its charter and has the capacity to act upon them. We believe in a multilateral system in which every state has both rights and And we believe that small-sized states have a particular role to play not on the margins of international affairs but as active participants in shaping our common future. And for the Republic of Cypus, that means defending the principles on which we depend, contributing to to the institutions which we believe, building partnerships for the common good, taking initiatives to create useful synergies, and acting responsibly when we can affect change."},{"t":1205,"topic":"Cyprus sovereignty","text":"Your excellencies, despite the challenges because of the Turkish occupation, we remain resilient as stefast in our faith in the multilateral system. Because in the end, the strength of multilateralism is measured by whether every member state believes that its voice matters, its rights are protected and its contribution has That is how we restore trust. That is how we manage transformation. And that is how we build a united nation that truly delivers for all. Thank you very much. On behalf of the assembly, I thank the president of the Republic of Cyprus."}],"compare":[{"topic":"Cyprus","share":0.5241,"mean":0.0007,"rank":1,"others":2},{"topic":"UN & its reform","share":0.1286,"mean":0.2052,"rank":131,"others":170},{"topic":"International Law & Order","share":0.1224,"mean":0.0601,"rank":37,"others":102},{"topic":"Israel–Palestine","share":0.0538,"mean":0.0524,"rank":66,"others":76}]};
